<?php include "../includes/auth.php"; include "../config/connection.php"; include "../includes/header.php"; $r=mysqli_query($conn,"SELECT id,name,email,city,salary FROM customers WHERE salary>20000 ORDER BY salary DESC"); ?>
<h2>Customers With Salary More Than 20,000</h2><div class="table-responsive"><table class="table table-bordered table-striped bg-white mt-3"><thead class="table-dark"><tr><th>ID</th><th>Name</th><th>Email</th><th>City</th><th>Salary</th></tr></thead><tbody><?php while($x=mysqli_fetch_assoc($r)): ?><tr><td><?php echo $x['id']; ?></td><td><?php echo htmlspecialchars($x['name']); ?></td><td><?php echo htmlspecialchars($x['email']); ?></td><td><?php echo htmlspecialchars($x['city']); ?></td><td><?php echo number_format($x['salary'],2); ?></td></tr><?php endwhile; ?></tbody></table></div><a href="../index.php" class="btn btn-secondary">Back Home</a><?php include "../includes/footer.php"; ?>